    "description": "Sestdien, 7. martā, Valmieras Olimpiskajā centrā norisinājās sporta deju sacensības un Latvijas Čempionāts Latīņamerikas dejās . Solo grupas dejotāja Ramona startēja divās sporta deju programmās. Solo Bērni I 2019.dz.g. un jaun. 1.-2.līmenis 2 dejas sacensībās un Solo Bērni I 2018.dz.g. un jaun. 1.-2.līmenis 3 dejas sacensībās, kur abās izcīnīja 1.vietas. Savas pirmās sporta deju sacensības aizvadīja Solo grupas dejotājas Rūta , Maija un Alise . Meitenes startēja Solo Bērni I 2019.dz.g. un jaun. 1.-2.līmenis 2 dejas sacensībās, kur Alise izcīnīja 1.vietu, bet Rūta un Maija ieguva 2.vietas. Solo grupas dejotāja Kristena startējot Solo Bērni I 2018.dz.g. un jaun. 1.-2.līmenis 3 dejas sacensībās ieguva 2.vietu. Arī Solo grupas dejotāja Elizabete aizvadīja savas pirmās sacensības, kur startējot Solo Bērni II 2015&lt; 2.-3.līmenis 4 dejas sacensībās izcīnīja 2.vietu. Iesācēju grupas dejotāji Jēkabs un Nora startējot Iesācēji Bērni I 2019.dz.g. un jaun. 1.līmenis 2 dejas sacensībās izcīnīja 1.vietu. Iesācēju grupas dejotāji Martins un Ieva startējot Iesācēji Bērni I 2018.dz.g. un jaun. 1.-2.līmenis 3 dejas sacensībās ieguva 1.vietu. Juniori I grupas Georgs un Olīvija startēja Juniori I E4 klases sacensībās, kur izcīnīja 2.vietu. Juniori I grupas dejotāji Haralds un Amanda startējot apvienotās Juniori I+II E6 klases sacensībās, izcīnīja 1.vietu. Juniori II grupas dejotāji Roberts un Alise startēja apvienotās Juniori II + Jaunieši D ST klases sacensībās izcīnīja 2.vietu. Pēc tam startējot Juniori II + Jaunieši D LA Latvijas Kausa izcīņas posma sacensībās, no pusfināla iekļūstot finālā ieguva 6.vietu. Bērni I grupas dejotāji Jānis un Lote startējot Bērni I E4 Latvijas Kausa izcīņas posma sacensībās, no pusfināla iekļūstot finālā, izcīnīja 3.vietu. Sveicam visus dejotājus ar labiem startiem sacensībās!",
