    "description": "Sestdien, 29. novembrī, Siguldā Sporta centrā norisinājās sporta deju sacensības Ziemassvētki Siguldā 2025 . Solo grupas dejotāja Kristena startējot Solo Iesācēji 2018.dz.g. un jaun. 2 dejas sacensībās izcīnīja 1.vietu. Solo grupas dejotāja Ramona startējot Solo Iesācēji 2019.dz.g. un jaun. 2 dejas sacensībās ieguva 1.vietu. Solo Bērni II 2014.dz.g. un jaun. E4 4 dejas sacensībās dejoja Rūta un ieguva 14.vietu. Savas pirmās kopīgās sacensības aizvadīja Iesācēju grupas dejotāji Martins un Ieva. Viņi startēja Iesācēji 2018.dz.g. un jaun. 1.līmenis 2 dejas sacensībās un izcīnīja 1.vietu. Iesācēju grupas dejotāji Jēkabs un Nora startējot Iesācēji 2018.dz.g. un jaun. 1.-2.līmenis 2 dejas sacensībās izcīnīja 1.vietu. Iesācēju grupas dejotāji Paulis un Katrīne startējot Iesācēji 2014.dz.g. un jaunāki 2.-3.līmenis 4 dejas sacensībās izcīnīja 1.vietu. Bērnu grupas dejotāji Jānis un Lote startēja Bērni I E4 klases sacensībās. Tās sākās ar pusfinālu. Pāris iekļūst finālā un izcīna 1.vietu. Bērnu grupas dejotāji Haralds un Amanda startējot Bērni II E4 klases sacensībās, no pusfināla iekļūstot finālā, izcīnīja 1.vietu. Juniori I grupas dejotāji Georgs un Olīvija startējot Juniori I E4 klases sacensībās izcīnīja 3.vietu. Juniori I grupas dejotāji Roberts un Alise startējot Juniori I E6 Latvijas Kausa izcīņas posma sacensībās, no pusfināla iekļūstot finālā, izcīnīja 1.vietu. Sveicam visus dejotājus ar veiksmīgiem startiem Siguldas sacensībās!",
