    "description": "Sestdien, 8.martā, Valmieras Olimpiskajā centrā norisinājās sporta deju sacensības un Latvijas čempionāts Standartdejās . Savas pirmās sacensības aizvadīja Solo grupas dejotāja Kristena . Viņa piedalījās Solo Iesācēji 2018.dz.g. un jaunāki 1.-2.līmenis 2 dejas sacensībās un ieguva 1.vietu. Solo grupas dejotāja Lauma startēja Solo 2014.dz.g. un jaunākas 4 dejas sacensībās, kur izcīnīja 5.vietu. Pirmo reizi uz sacensībām devās Iesācēju grupas dejotāji Jēkabs un Nora. Pāris startēja Iesācēji 2018.dz.g. un jaunāki 1.līmenis 2 dejas sacensībās, kur izcīnīja 1.vietu. Arī savas pirmās sacensības aizvadīja Iesācēju grupas dejotāji Matvejs un Paula . Viņi startēja Iesācēji 2017.dz.g. un jaunāki 1.-2.līmenis 2 dejas sacensībās un izcīnīja 1.vietu. Iesācēju grupas dejotāji Martins un Karlīna startēja divās programmās. Gan Iesācēji 2017.dz.g. un jaunāki 1.-2.līmenis 2 dejas sacensībās, gan Iesācēji 2016.dz.g. un jaunāki 1.-2.līmenis 3 dejas sacensībās, abās izcīnīja 2.vietas. Iesācēji 2016.dz.g. un jaunāki 1.-2.līmenis 3 dejas sacensībās arī dejoja Adrians un Felicita un izcīnīja 2.vietu. Iesācēju grupas dejotāji Paulis un Katrīne startējot Iesācēji 2015.dz.g. un jaunāki 2.-3.līmenis 4 dejas sacensībās ieguva 2.vietu. Bērni II E4 klases sacensībās startēja Bērnu grupas dejotāji Haralds un Amanda . Viņiem sacensības sākās ar pusfinālu. Pāris iekļūstot finālā izcīnīja 2.vietu. Juniori I grupas dejotāji Roberts un Alise startējot Juniori I E6 klases sacensībās izcīnīja 1.vietu. Latvijas čempionātā Standartdejās Juniori I grupā startēja Sendijs un Elvita . Viņiem sacensības sākās ar pusfinālu. Pāris iekļūst finālā un izcīna 4.vietu. Sveicam visus dejotājus ar labiem panākumiem sacensībās!",
