    "location": "Latvija",
    "category": "Čempionāts",
    "description": "Sestdien, 25.janvārī, Rēzeknē Latgales vēstniecībā \"Gors\" norisinājās Latvijas čempionāts 10 dejās . Rīta pusē Meiteņu solo grupā dejoja Rūta . Viņa startēja Meitenes solo 2014.dz.g. un jaunākas 2.-3.līmenis 4 dejas sacensībās un ieguva 3.vietu. Iesācēju grupas dejotāji Georgs un Olīvija startējot Iesācēji 2010.dz.g. un jaunāki 2.-3.līmenis 4 dejas sacensībās ieguva 2.vietu. Bērnu grupas dejotāji Haralds un Amanda pirmo reizi startēja vairākās sacensībās. Vispirms pāris startēja Bērni II E4 klases sacensībās, kur no pusfināla iekļūstot finālā izcīnīja 3.vietu. Pēc tam dejotāji startēja Bērni II E4 Latvijas Kausa izcīņas posma sacensībās, kur no ceturtdaļfināla iekļūstot finālā izcīnīja 6.vietu. Nu jau kā Juniori I grupas dejotāji savas pirmās sacensības aizvadīja Sendijs un Elvita . Pāris startēja Latvijas Valsts čempionātā 10 dejās, kur Junioru I grupa dejo 8 dejas. Sacensības sākās ar pusfinālu. Sendijs un Elvita iekļūstot finālā izcīnīja 3.vietu. Iesācēju grupas dejotāji Martins un Karlīna dejoja Iesācēji B/D 1.-2.līmenis 2 dejas sacensībās un izcīnīja 1.vietu. Sveicam visus dejotājus ar labiem panākumiem sacensībās!",
