    "category": "Reitings",
    "description": "Sestdien, 27.aprīlī, Rīgā Teikas vidusskolā norisinājās sporta deju sacensības Pavasara Ritmos 2024 . Solo grupas dejotāja Rūta startēja divās disciplīnās. Solo 2015.dz.g. un jaunāki 3 dejas sacensībās un Solo 2015.dz.g. un jaunāki 4 dejas sacensības. Abās izcīnīja 2.vietas. Solo grupas dejotāja Lauma arī startēja divās disciplīnās. Solo 2014.dz.g. un jaunāki 4 dejas sacensībās, kur ieguva 2.vietu. Savukārt startējot Solo 2013.dz.g. un jaunāki 3 dejas sacensībās izcīnīja 1.vietu. Iesācēju grupas dejotāji Martins un Karlīna startējot Iesācēji 2016.dz.g. un jaunāki 1.līm. 2 dejas sacensībās izcīnīja 1.vietu. Iesācēju grupas dejotāji Artūrs un Amēlija startējot Iesācēji 2016.dz.g. un jaunāki 1.līm. 2 dejas sacensībās un Iesācēji 2016.dz.g. un jaunāki 1.-2.līm. 3 dejas sacensībās, abās izcīnīja 1.vietas. Iesācēju grupas dejotāji Emīls un Dārta startējot Iesācēji 2016.dz.g. un jaunāki 1.-2.līm. 3 dejas sacensībās izcīnīja 1.vietu. Savukārt startējot Iesācēji 2016.dz.g. un jaunāki 1.-2.līm. 4 dejas sacensībās ieguva 2.vietu. Savas pirmās sacensības aizvadīja Iesācēju grupas dejotāji Viktors un Enija . Pāris startēja Iesācēji 2014.dz.g. un jaunā 1.-2.līm. 3 dejas sacensībās un izcīnīja 1.vietu. Savas pirmās sacensības ka Bērni II E4 klases dejotāji aizvadīja Haralds un Amanda . Dejotāji startēja Bērni II E4 klases sacensībās, kur no pusfināla iekļūstot finala izcīnīja 5.vietu. Iesācēju grupas dejotāji Georgs un Olīvija startējot Iesācēji 2013.dz.g. un jaunāki 2.-3.līmenis 4 dejas sacensībās ieguva 2.vietu. Juniori I grupas dejotāji Roberts un Emīlija startējot Juniori I E6 klases sacensībās izcīnīja 1.vietu. Arī vēlāk startējot Juniori I + II E6 klases sacensībās pāris izcīnīja 1.vietu. Sveicam visus dejotājus ar lieliskiem panākumiem sacensībās!",
