    "id": "comp-5647",
    "raw_id": "5647",
    "title": "Latvijas čempionāts Latīņamerikas dejās 2024",
    "date": "2024-03-10",
    "year": "2024",
    "location": "Latvija",
    "category": "Čempionāts",
    "description": "Sestdien, 9.martā, Valmieras olimpiskajā centrā norisinājās Latvijas čempionāts Latīņamerikas dejās 2024 . Rīta pusē Solo grupas dejotāja Rūta startēja Meitenes solo 2015.dz.g. un jaun. 3 dejas un Meitenes solo 2014.dz.g. un jaun. 4 dejas sacensībās, kur abās izcīnīja 1.vietas. Solo grupas dejotāja Lauma piedaloties Meitenes solo 2014.dz.g. un jaun. 4 dejas sacensībās izcīnīja 1.vietu. Savas pirmās sporta deju sacensības aizvadīja trīs jaunākie SDK \"Zīle\" deju pāri. Iesācēji 2017.dz.g. un jaun. 1.līmenis 2 dejas dejoja Adrians ar Felicitu , Martins ar Karlīnu un Artūrs ar Amēliju . Visi trīs pāri izcīnīja 1.vietas. Vairāki pāri piedalījās Iesācēji 2015.dz.g. un jaun. 1.-2.līmenis 2 dejas sacensībās. Emīls ar Dārtu , Paulis ar Katrīni un Jānis ar Loti . Visi pāri izcīnīja 1.vietas. Iesācēji 2012.dz.g. un jaun. 1.-2.līmenis 3 dejas sacensībās piedalījās Georgs ar Olīviju un izcīnīja 2.vietu. Juniori I E4 klases dejotāji Roberts un Emīlija startēja Juniori I E6 Latvijas kausa izcīņas posma sacensībās, kur no ceturtdaļfināla iekļuva pusfinālā un izcīnīja 7.vietu. Latvijas čempionātā Latīņamerikas dejās, kur Bērnu grupā dejo 4 latīņamerikas dejas startēja Bērni II E6 klases pāris Sendijs un Elvita . Sacensības sākās ar pusfinālu un Sendijs ar Elvitu pārliecinoši iekļūstot finalā izcīnīja 1.vietu. Sveicam visus dejotājus ar izciliem panākumiem sacensībās!",
