    "description": "Sestdien, 3.jūnijā, Rīgā Hanzas vidusskolas sporta hallē norisinājās sporta deju sacensības Mūsu Cerības 2023 . Meiteņu solo grupas dejotāja Rūta startēja divās sacensībās. Vispirms startējot Meitenes solo 2015.dz.g. un jaun. - 3 dejas sacensībās, viņa izcīnīja 1.vietu. Savukārt vēlāk startējot Meitenes solo 2014.dz.g. un jaun. - 4 dejas sacensībās ieguva 2.vietu. Meiteņu solo grupas dejotāja Alise startējot Meitenes solo 2014.dz.g. un jaun. - 4 dejas sacensībās izcīnīja absolūto 1.vietu. Bērnu grupas dejotāji Robins un Sintija startēja vairākās sacensību programmās. Vispirms pāris dejoja Bērni I+II E4 klases sacensībās, kur izcīnīja 2.vietu. Tad startēja Bērni II E4klases sacensībās, kur izcīnīja 3.vietu. Un vēlāk vēl startēja Bērni I+II E6 klases sacensībās, kur izcīnīja 2.vietu. Sveicam visus dejotājus ar labiem rezultātiem sacensībās! Ar šīm sacensībām esam veiksmīgi noslēguši 2022/2023. gada sporta deju sezonu. Liels paldies treneriem Evelīnai, Uģim un Ivetai par ieguldīto darbu, dejotājiem par mērķtiecību un neatlaidību, un vecākiem par izturību un atbalstu!",
