    "description": "Sestdien, 18. februārī, Valmieras Olimpiskajā centrā norisinājās Latvijas valsts čempionāts standartdejās . Meiteņu solo grupas dejotājas Alise un Rūta , abas startēja Meitenes solo 2014.dz.g. un jaun. 1.-2.līmenis 2 dejas sacensībās un abas izcīnīja 1.vietas. Savas pirmās sacensības Iesācēju grupā aizvadīja Haralds ar divām partnerēm Amandu un Laumu . Pāri startēja Iesācēji 2012. dz.g. un jaun. 1.-2.līmenis 2 dejas sacensībās, un Haralds ar abām partnerēm Amandu un Laumu izcīnīja 1.vietas. Juniori I E4 klases pāris Aleksis un Julianna startējot Juniori I+II E4 grupas sacensībās no ceturtdaļfināla iekļūstot finālā izcīnīja 7.vietu. Savukārt vēlāk startējot Juniori I E6 Latvijas kausa izcīņas posma sacensībās no ceturtdaļfināla iekļūstot pusfinālā, dala 11.-12.vietu. Bērnu grupas dejotāji Sendijs ar Elvitu un Roberts ar Emīliju startēja Bērni I+II E6 Latvijas kausa izcīņas posma sacensībās, kur Sendijs un Elvita izcīnīja 2.vietu, savukārt Roberts un Emīlija ierindojās 7.vietā. Sveicam visus dejotājus ar labiem panākumiem sacensībās!",
